num={'type':'number'};positive={'type':'number','exclusiveMinimum':0};text={'type':'string','minLength':1};integer={'type':'integer','minimum':0};sha={'type':'string','pattern':'^[a-f0-9]{64}$'};uv={'type':'object','required':['u','v'],'properties':{'u':num,'v':num}};xy={'type':'object','required':['x','y'],'properties':{'x':num,'y':num}}
