register('arkadia.stronghold-prefab.v1','base',obj({'id':const('stronghold'),'version':const(1),'anchor':uv,'world':obj({'width':positive,'height':positive}),'court':obj({'size':positive,'origin':xy,'walkInset':num,'openSnowFrom':num}),'gate':obj({'x':num,'threshold':xy,'passageFromY':num,'archHalfWidth':positive,'towerHalfSpan':positive,'towerFront':obj({'knee':num,'base':num,'rise':num,'peak':num,'fall':num}),'towerDepth':positive,'columnStep':positive,'doors':obj({'halfWidth':positive,'back':num,'front':num}),'trigger':obj({'y':num,'closed':xy,'open':xy}),'frontY':num,'footprintHeight':obj({'tower':positive,'doors':positive}),'apron':{'type':'object'},'frames':{'type':'integer','minimum':2},'passableAt':num}),'safeZone':obj({'metersPerTile':positive,'center':uv,'spawnDistanceM':positive}),'heroSpawn':xy,'buildings':{'type':'object','additionalProperties':obj({'x':num,'y':num,'width':positive,'pivot':num,'asset':text,'groundEdges':{'type':'object'}})},'props':arr(obj({'group':text,'id':text,'u':num,'v':num,'width':positive},['group','id','u','v','width'])),'lights':arr(obj({'u':num,'v':num,'lift':num,'wall':{'type':'boolean'}}))}))
register('arkadia.character-atlas.v1','character',obj({'id':text,'image':text,'atlasSize':fixed(2),'scale':positive,'gutter':num,'cell':obj({'w':positive,'h':positive,'pivot':xy}),'direction':text,'clips':{'type':'object','additionalProperties':clip},'frames':arr(obj({'row':integer,'col':integer,'x':num,'y':num,'w':positive,'h':positive,'source':{'type':'object'}}))}))
register('arkadia.equipment-atlas.v1','character',obj({'image':text,'atlasSize':fixed(2),'icon':integer,'items':arr(obj({'id':text,'x':num,'y':num,'w':positive,'h':positive,'source':{'type':'object'}}))}))
register('arkadia.hero-glb.v1','character',obj({'hero':text,'name':text,'glb':text,'thumbnail':text,'animations':arr(obj({'slug':{'enum':['idle','run','idle_cast','run_cast','hit','death']},'label':text,'loop':{'type':'boolean'}}))}))
register('arkadia.sprite-sheet.v1','animation',obj({'title':text,'source':text,'columns':{'type':'integer','minimum':1,'maximum':256},'rows':{'type':'integer','minimum':1,'maximum':256},'frameCount':{'type':'integer','minimum':1},'fps':{'type':'number','minimum':1,'maximum':60},'pivot':obj({'x':{'type':'number','minimum':0,'maximum':1},'y':{'type':'number','minimum':0,'maximum':1}}),'loop':{'type':'boolean'}},['title','source','columns','rows','fps','pivot']))
register('arkadia.gltf.v2','animation',obj({'asset':obj({'version':const('2.0')}),'animations':arr(obj({'name':text,'samplers':arr({'type':'object'}),'channels':arr({'type':'object'})})),'nodes':arr({'type':'object'}),'accessors':arr({'type':'object'})}))
