register('arkadia.economy-rules.v1','base',obj({'balance':obj({'hours':positive,'goldPerHour':num,'manaPerHour':num,'maxLevel':integer,'upgradeBase':num,'start':{'type':'object'}}),'buildings':arr(text),'startBuilt':arr(text),'upgradeSamples':arr(obj({'building':text,'level':integer,'cost':obj({'gold':num,'mana':num,'souls':num})})),'defenseBranches':{'type':'object'},'defenseMinCore':integer,'defenseCost':{'type':'object'},'defenseCombat':{'type':'object'}}))
