patchFields={k:{'type':'number','minimum':lo,'maximum':hi} for k,lo,hi in [('order',0,512),('opacity',0,1),('size',.02,8),('count',0,4),('rate',0,4),('lifetime',.05,8),('speed',0,8),('direction',-180,180),('spread',0,360),('gravity',-20,20),('x',-10,10),('y',-10,10),('z',-10,10),('delay',0,10),('duration',.01,10),('columns',1,16),('rows',1,16),('fps',1,120),('frameCount',1,256),('pivotX',0,1),('pivotY',0,1)]}
