v2=obj({'schemaVersion':const(2),'kind':{'enum':sorted({k for k,_ in formats.values()})},'name':{'type':'string','minLength':1,'maxLength':160},'assets':{'type':'array','maxItems':2048,'uniqueItems':True,'items':sha},'dependencies':arr(obj({'id':{'type':'string','pattern':'^[a-zA-Z0-9_-]{1,100}$'},'kind':text,'revision':{'type':'integer','minimum':1}})),'provenance':obj({'repository':text,'sourcePath':text,'selector':{'type':'string'},'sourceSha256':sha,'legacyId':text}), 'data':obj({'format':{'enum':list(formats)},'payload':{'type':'object'},'bindings':{'type':'object','additionalProperties':sha}})})
